use crate::domain::shared::ValidationError;

/// Whether a caption track was uploaded by the video's creator or
/// auto-generated by YouTube; stored as `MANUAL` / `AUTOMATIC`.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum CaptionSource {
    Manual,
    Automatic,
}

impl CaptionSource {
    pub fn as_str(&self) -> &'static str {
        match self {
            Self::Manual => "MANUAL",
            Self::Automatic => "AUTOMATIC",
        }
    }

    pub fn parse(value: &str) -> Result<Self, ValidationError> {
        match value {
            "MANUAL" => Ok(Self::Manual),
            "AUTOMATIC" => Ok(Self::Automatic),
            other => Err(ValidationError(format!("unknown caption source '{other}'"))),
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn it_should_round_trip_every_source_through_its_string_representation() {
        let sources = [CaptionSource::Manual, CaptionSource::Automatic];

        assert_eq!(
            sources.map(|source| CaptionSource::parse(source.as_str())),
            sources.map(Ok)
        );
    }

    #[test]
    fn it_should_reject_an_unknown_source() {
        assert_eq!(
            CaptionSource::parse("BOGUS"),
            Err(ValidationError(
                "unknown caption source 'BOGUS'".to_string()
            ))
        );
    }
}
